def gen(rng):
    def fmt(a, ops):
        return f'{len(a)}\n' + ' '.join(map(str, a)) + f'\n{len(ops)}\n' + '\n'.join(' '.join(map(str, o)) for o in ops)
    def rand_ops(n, q, vmax, pupd):
        ops = []
        for _ in range(q):
            if rng.random() < pupd:
                ops.append((1, rng.randrange(n), rng.randint(0, vmax)))
            else:
                l = rng.randrange(n)
                r = rng.randrange(n)
                if l > r:
                    l, r = r, l
                ops.append((2, l, r))
        if all(o[0] == 1 for o in ops):
            ops[-1] = (2, 0, n - 1)
        return ops
    def rand_case(n, q, vmax, pupd=0.5):
        return fmt([rng.randint(0, vmax) for _ in range(n)], rand_ops(n, q, vmax, pupd))
    M = 10**9
    tests = [
        fmt([5], [(2, 0, 0)]),
        fmt([5], [(1, 0, 9), (2, 0, 0)]),
        fmt([1, 2, 3, 4, 5], [(2, 0, 4), (1, 2, 7), (2, 1, 3), (2, 2, 2)]),
        fmt([8, 8, 8], [(2, 0, 1), (2, 0, 2), (2, 1, 2)]),
        fmt([M, M, 0, M], [(2, 0, 3), (1, 2, M), (2, 0, 3), (1, 0, 0), (2, 0, 3)]),
        fmt([0, 0, 0, 0], [(2, 0, 3), (1, 3, 1), (2, 0, 3), (2, 0, 2)]),
    ]
    for n, q in ((2, 5), (3, 8), (5, 10), (8, 15), (10, 20), (16, 25), (30, 20)):
        for _ in range(2):
            tests.append(rand_case(n, q, rng.choice([3, 15, 255]), rng.choice([0.2, 0.5, 0.8])))
    tests.append(rand_case(5000, 20000, M, 0.5))
    tests.append(rand_case(100000, 100000, 10**4, 0.5))
    tests.append(rand_case(100000, 100000, 10**4, 0.2))
    tests.append(rand_case(100000, 100000, 10**4, 0.8))
    return tests
